#!/usr/bin/env bash
set -uo pipefail
G=$(docker ps --format '{{.Names}}' | grep -E 'gateway' | head -1)
docker exec "$G" node -e "const run=async()=>{const pg=await import('pg');const c=new pg.default.Client({connectionString:process.env.DATABASE_URL});await c.connect();const apps=await c.query('SELECT id,slug,name,org_id,tier FROM sdk_applications ORDER BY slug LIMIT 30').catch(e=>({rows:[]}));for(const r of apps.rows)console.log('APP slug='+r.slug+' org='+r.org_id+' tier='+r.tier+' name='+r.name);const demo=await c.query(\"SELECT id,slug,org_id FROM sdk_applications WHERE slug ILIKE 'nsp' OR slug ILIKE 'demo' OR name ILIKE 'demo' OR org_id IN ('10000000','1','2','3','4') LIMIT 20\").catch(()=>({rows:[]}));console.log('--- demo-ish apps ---');for(const r of demo.rows)console.log('DEMO_APP slug='+r.slug+' org='+r.org_id);const orgtbl=await c.query(\"SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name LIKE '%org%'\").catch(()=>({rows:[]}));console.log('ORG_TABLES',orgtbl.rows.map(r=>r.table_name).join(','));for(const t of ['nv_organizations','organizations','orgs','tenant_organizations']){try{const r=await c.query('SELECT COUNT(*)::int n FROM '+t);console.log(t+'_count',r.rows[0].n);const s=await c.query('SELECT * FROM '+t+' ORDER BY 1 LIMIT 8');for(const row of s.rows)console.log(t,JSON.stringify(row).slice(0,200));}catch(e){}}await c.end();};run().catch(e=>{console.error('ERR',e.message);process.exit(1);});"
